/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_rol_after_update` AFTER UPDATE ON `rol` FOR EACH ROW BEGIN
    INSERT INTO Bitacora (id_usuario, tabla_afectada, id_registro_afectado, tipo_operacion, descripcion)
