CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_limpiar_datos_simulacion`()
BEGIN
    SET FOREIGN_KEY_CHECKS = 0;

    TRUNCATE TABLE Pago;
    TRUNCATE TABLE Detalle_pedido;
    TRUNCATE TABLE Pedido;
    TRUNCATE TABLE Reservacion;
    
    DELETE FROM Usuario WHERE id_rol != 1;
    ALTER TABLE Usuario AUTO_INCREMENT = 6;

    SET FOREIGN_KEY_CHECKS = 1;

    SELECT 'Simulación limpiada exitosamente. Se conservaron los 5 administradores y las transacciones fueron reiniciadas.' AS resultado;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
